// Topic: umweltbox/{tenant-id}/{device-id}/{category}/{measurement}
const parts = msg.topic.split("/");

if (parts.length < 2 || parts[0] !== "umweltbox") {
    return null;
}

const tenant_id = parts[1];
let device_id = parts[2] || "unknown";
let category = parts[3] || "default";
let measurement = parts[4] || "value";

// Extrahiere Daten aus Payload
let payloadObj = msg.payload;
if (typeof msg.payload === "string") {
    try {
        payloadObj = JSON.parse(msg.payload);
    } catch (e) {
        payloadObj = { value: parseFloat(msg.payload) };
    }
} else if (typeof msg.payload === "number") {
    payloadObj = { value: msg.payload };
}

// Spezielle Logik für Tasmota SENSOR-Meldungen
if (payloadObj.AM2301) {
    const sensor = payloadObj.AM2301;
    const timestamp = Date.now() * 1000000;
    const baseTags = `tenant_id=${tenant_id},device_id=${device_id},category=environment`;

    let lp = [];
    if (sensor.Temperature !== undefined) lp.push(`sensors,${baseTags},sensor_type=temperature value=${sensor.Temperature} ${timestamp}`);
    if (sensor.Humidity !== undefined) lp.push(`sensors,${baseTags},sensor_type=humidity value=${sensor.Humidity} ${timestamp}`);
    if (sensor.DewPoint !== undefined) lp.push(`sensors,${baseTags},sensor_type=dewpoint value=${sensor.DewPoint} ${timestamp}`);

    if (lp.length > 0) {
        msg.payload = lp.join("\n");
    } else {
        return null;
    }
} else {
    // Standardwert
    let value;
    if (payloadObj.value !== undefined) {
        value = parseFloat(payloadObj.value);
    } else if (typeof payloadObj === "number") {
        value = payloadObj;
    } else {
        return null;
    }

    if (isNaN(value)) return null;

    // Einheitlicher Sensor-Name
    if (measurement === "temp") measurement = "temperature";

    const timestamp = Date.now() * 1000000;
    msg.payload = `sensors,tenant_id=${tenant_id},device_id=${device_id},category=${category},sensor_type=${measurement} value=${value} ${timestamp}`;
}

msg.url = `http://influxdb:8181/api/v3/write_lp?db=mintfv&precision=ns`;
const token = env.get("INFLUXDB_TOKEN");
if (!token) {
    node.error("INFLUXDB_TOKEN not set!");
    return null;
}

msg.headers = {
    "Authorization": "Bearer " + token,
    "Content-Type": "text/plain"
};

return msg;

if (msg.statusCode === 204 || msg.statusCode === 200) {
    node.status({fill:"green",shape:"dot",text:"OK"});
} else {
    node.status({fill:"red",shape:"dot",text:"Error " + msg.statusCode});
    node.error("InfluxDB Error: " + msg.statusCode + " - " + msg.payload);
}
return msg;
